#!/bin/bash

# Setup script for cron-job.org integration
# This script helps configure cron-job.org to call your Vercel API endpoints

set -e

echo "🚀 Yuvoo Cron Jobs - cron-job.org Setup"
echo "========================================"
echo ""

# Check if CRON_SECRET is set
if [ -z "$CRON_SECRET" ]; then
  echo "⚠️  CRON_SECRET environment variable not set"
  echo "Please set it first:"
  echo "  export CRON_SECRET='your-secret-key'"
  exit 1
fi

# Get Vercel app URL
if [ -z "$VERCEL_APP_URL" ]; then
  echo "⚠️  VERCEL_APP_URL environment variable not set"
  read -p "Enter your Vercel app URL (e.g., https://yuvoo.vercel.app): " VERCEL_APP_URL
fi

echo "📋 Configuration Details:"
echo "  Vercel App URL: $VERCEL_APP_URL"
echo "  CRON_SECRET: ${CRON_SECRET:0:10}..."
echo ""

echo "📝 Instructions for cron-job.org:"
echo ""
echo "1. Go to https://cron-job.org and sign up/login"
echo "2. (Optional) Consider Sustaining Membership for enhanced limits:"
echo "   - 5-minute timeout (vs 30 seconds)"
echo "   - 256 KB response size (vs 64 KB)"
echo "   - 5,000 API calls/day (vs 100)"
echo "   - €5-20/month or €12-36/year (your choice)"
echo "3. Click 'Create cronjob'"
